installation.script:
#!/bin/bash

echo "🚀 Installation Node.js NeoHeberg..."
echo "📁 Création de la structure de base..."

mkdir -p /mnt/server
cd /mnt/server

if [ ! -f package.json ]; then
    echo "📦 Création d'un package.json de base..."
cat > package.json << 'EOF'
{
  "name": "neoheberg-nodejs-app",
  "version": "1.0.0",
  "description": "Application Node.js générée automatiquement par NeoHeberg",
  "main": "index.js",
  "scripts": {
    "start": "node index.js"
  },
  "dependencies": {}
}
EOF
fi

if [ ! -f index.js ]; then
    echo "📄 Création du fichier index.js par défaut..."
cat > index.js << 'EOF'
const http = require('http');

const port = process.env.SERVER_PORT;

if (!port) {
  console.error("❌ Aucun port trouvé dans les variables d'environnement.");
  process.exit(1);
}

const server = http.createServer((req, res) => {
  res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });
  res.end(`
    <div style="font-family: Arial; text-align: center; padding: 40px;">
      <h1>🚀 Serveur Node.js NeoHeberg</h1>
      <p>✅ Serveur en ligne</p>
      <p><strong>Node:</strong> ${process.version}</p>
      <p><strong>Port:</strong> ${port}</p>
    </div>
  `);
});

server.listen(port, '0.0.0.0', () => {
  console.log(`✅ Serveur NeoHeberg démarré sur le port ${port}`);
  console.log(`🌐 Application accessible sur http://0.0.0.0:${port}`);
});

process.on('SIGTERM', () => {
  console.log('🛑 Arrêt du serveur...');
  server.close(() => {
    console.log('✅ Serveur arrêté proprement');
    process.exit(0);
  });
});
EOF
fi

echo ""
echo "✅ Installation terminée pour NeoHeberg !"
echo "📋 Fichiers présents :"
ls -la

echo ""
echo "ℹ️  Les dépendances npm seront automatiquement installées à chaque démarrage du serveur."
